import { useEffect, useReducer, useState } from 'react';
import {Image, View} from 'react-native';

import {
  Menu,
  MenuOptions,
  MenuOption,
  MenuTrigger,
  renderers
} from 'react-native-popup-menu';

import { 
  COLORS, 

  AvatarContact, 
  CallButton, 
  CallIcon, 
  CancelAccept, 
  CancelAcceptCall, 
  Link, 
  Text, 
  Screen, 
  fontSizes,
  resizeRel
} from './Basics';

import { Player } from './Player';
import { DialGrid } from './Dialer';
import Timer from './Timer';
import { VPhone } from '../phone/VPhone';
import { useStore } from '../phone/store';
import { Icon } from './Icons';
import { isWeb } from '../utils';

const { Popover } = renderers;

export const SessionScreen = ({
  session,
  speaker,

  onAccept,
  onCancel,

  onContactClick,

  allowTransfer = true,
  allowBlindTransfer = true,
  onTransfer,
  onBlindTransfer,
  isTransfer,
}) => {
  const { devices } = useStore();

  const [_, forceUpdate] = useReducer(x => x + 1, 0);
  const [showDialer, setShowDialer] = useState(false);

  const update = () => setTimeout(forceUpdate, 25);
  
  useEffect(() => {
    if (!session) return;
    
    session.stateChange?.addListener(update);

    return () => {
      session.stateChange?.removeListener(update);
    }
  }, [session, update]);


  if (!session?.id) return null;
  
  const dialHandler = key => session.dtmf(key);

  const holdHandler = async () => {
    await session.setHold(!session.isHold());
    update();
  }

  const muteHandler = () => {
    session.setMuted(!session.isMuted());
    update();
  }

  const muteVideoHandler = () => {
    session.setMutedVideo(!session.isMutedVideo());
    update();
  }

  const { fake } = session;
  const initial = session.isEstablished?.() || session?.isDirtyAnswered?.() || fake;
  const established = session.isEstablished?.();
  const isVideo = session.isVideo();
  const isInbound = session.isInbound();

  const { cdr: { from, to, contact } = {} } = session;
  const number = isInbound ? from : to || contact?.phones?.[0] || '';
  const paddingTop = isWeb ? 15 : 30;
  const showButtons = !fake;
  const textColor = isVideo ? COLORS.primary : COLORS.text;

  return (
    <Screen closeable={false} visible={true}>

      <Player stream={session.getStream?.()} isvideo={session.isVideo()} speaker={speaker} />
      {session.isVideo() && session.cdr.contact?.avideo && 
        <Image style={{ width: '100%', height: '100%', backgroundColor: '#000000' }} source={{ uri: 'https://media.istockphoto.com/id/1319103417/photo/inspired-female-teacher-in-headphones-meet-students-online-give-class.jpg?s=612x612&w=0&k=20&c=cSGIQIwPFpVi7m4MR2_SLlwDcpBELdnNnLNgdtH6Bak=' }} />
      }

      <View style={{ width: '100%', height: '100%', position: 'absolute' }}>

        <View style={{ flexDirection: 'row', justifyContent: 'flex-end', alignItems: 'center', padding: resizeRel(5) }} >
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', alignContent: 'center', width: resizeRel(80), backgroundColor: COLORS.secondary, padding: resizeRel(5), borderRadius: resizeRel(15) }}>
            <CallIcon call={session.cdr} color="white" size={14} />

            {established &&
              <Timer style={{ color: 'white' }} />
            }
          </View>
        </View>

        <View style={{ flex: 1, padding: 10 }}>
          {showDialer ? (
            <DialGrid onPress={dialHandler} style={{ width: '100%', height: '100%', backgroundColor: COLORS.app }} />
          ) : (!isVideo || (isVideo && !established)) && (
            <View style={{ flex: 1, alignItems: 'center' }} >
              <AvatarContact size={100} contact={contact} />

              {contact?.name &&
                <Link onClick={() => onContactClick?.(contact)} style={{ fontSize: fontSizes.xxl, marginTop: 10, color: textColor }} 
                  numberOfLines={1} ellipsizeMode="tail">
                  {contact.name}
                </Link>
              } 

              <Text style={{ fontSize: fontSizes.xl, marginTop: contact?.name ? 5 : 10, color: textColor }} 
                numberOfLines={1} ellipsizeMode="tail" >
                  {number}
              </Text>
            </View>
          )}
        </View>

        {showButtons && (
          <View
            style={{
              flexDirection: 'row',
              justifyContent: 'space-around',
              backgroundColor: `${COLORS.app}90`,
              padding: 10,
              marginHorizontal: 10,
              borderRadius: 10,
            }}
          >
            <CallButton 
              icon={showDialer ? 'user' : 'grid'} 
              onClick={() => setShowDialer(!showDialer)} 
            />

            <CallButton
              iconColor={session._muted ? 'danger' : undefined}
              icon="mic-off"
              onClick={muteHandler}
            />
            
            {isVideo &&
              <CallButton
                iconColor={session._mutedVideo ? 'danger' : undefined}
                icon="video"
                onClick={muteVideoHandler}
              />
            }
            
            <Menu renderer={Popover}>
              <MenuTrigger>
                <CallButton icon="volume-2"/>
              </MenuTrigger>

              <MenuOptions>
                {devices.map((device, i) => {
                  const { deviceId, label, selected } = device;
                  return (
                    <MenuOption
                      key={`speaker-${i}`}
                      onSelect={() => VPhone.setSpeaker({ deviceId })}>
                        <View style={{ flexDirection: 'row', padding: 5 }}>
                          <Text size={20} style={{ paddingRight: 10 }}>{label}</Text>
                          {(isWeb ? speaker === deviceId : selected) && <Icon size={20} icon="check" />}
                        </View>
                    </MenuOption>
                  );
                })}
              </MenuOptions>
            </Menu>
         
            <CallButton
              icon={session._hold ? 'play' : 'pause'}
              onClick={holdHandler}
            />
            
            {established && allowTransfer && (
              <CallButton
                icon="phone-forwarded" 
                onClick={onTransfer} 
              />
            )}

            {established && allowBlindTransfer && (
              <CallButton
                testID="blindTransferButton"
                iconColor="danger"
                icon="phone-forwarded"
                onClick={onBlindTransfer}
              />
            )}
          </View>
        )}
        
        <View style={{ paddingTop, paddingBottom: isWeb ? 20 : 30 }}>
          {isTransfer ?
            <CancelAccept
              onAccept={initial ? onAccept : null} 
              onCancel={onCancel}
              cancelTestID="hangupButton"
              acceptTestID="acceptCallButton"
            /> :
            <CancelAcceptCall
              onAccept={session?.isInbound() && !initial && !fake? onAccept : null} 
              onCancel={onCancel}
              cancelTestID="hangupButton"
              acceptTestID="acceptCallButton"
            />
          }
        </View>

      </View>
    </Screen>
  );
};
